-- Refresh Chinese ingredient translations for the 2026-08-29 catalog while preserving a recoverable source snapshot.
CREATE TABLE IF NOT EXISTS product_ingredient_translation_backups (
  batch_id TEXT NOT NULL,
  product_id BIGINT NOT NULL,
  slug TEXT NOT NULL,
  ingredients TEXT,
  old_updated_at TEXT,
  backed_up_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (batch_id, product_id)
);

CREATE TEMP TABLE product_ingredient_translation_payload_20260829 (
  slug TEXT PRIMARY KEY,
  source_ingredients TEXT,
  ingredients_zh TEXT NOT NULL,
  translation_status TEXT NOT NULL
) ON COMMIT DROP;


SELECT 'ingredients-zh-cn-v2', p.id, p.slug, p.ingredients, p.updated_at::TEXT
FROM products p
JOIN product_ingredient_translation_payload_20260829 t ON t.slug = p.slug
ON CONFLICT (batch_id, product_id) DO NOTHING;

UPDATE products p
SET ingredients = t.ingredients_zh,
    updated_at = CURRENT_TIMESTAMP
FROM product_ingredient_translation_payload_20260829 t
WHERE p.slug = t.slug
  AND p.ingredients IS DISTINCT FROM t.ingredients_zh;

DO $$
DECLARE
  mismatch_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO mismatch_count
  FROM product_ingredient_translation_payload_20260829 t
  JOIN products p ON p.slug = t.slug
  WHERE p.ingredients IS DISTINCT FROM t.ingredients_zh;
  IF mismatch_count <> 0 THEN
    RAISE EXCEPTION 'Chinese ingredient verification failed for % products', mismatch_count;
  END IF;
END $$;
